INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué es el Botox?', 'El Botox es el nombre comercial más conocido de la toxina botulínica. Es una sustancia que disminuye temporalmente la actividad de determinados músculos, ayudando a suavizar las líneas de expresión.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué es el Botox?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Para qué sirve?', 'Se utiliza principalmente para disminuir arrugas dinámicas, es decir, aquellas que aparecen o se hacen más visibles con los movimientos musculares.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Para qué sirve?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué zonas se pueden tratar?', 'Dependiendo de la valoración y del producto utilizado, puede aplicarse en zonas como entrecejo, frente, bunny lines y patas de gallo, entre otras indicaciones específicas.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué zonas se pueden tratar?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿El Botox rellena las arrugas?', 'No. La toxina botulínica no funciona como un relleno. Su acción consiste en reducir temporalmente la contracción muscular que contribuye a formar las líneas de expresión.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿El Botox rellena las arrugas?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿El resultado se ve inmediatamente?', 'No. El efecto aparece progresivamente después de la aplicación. Generalmente comienza a notarse durante los primeros 3 días y alcanza su efecto máximo posteriormente a los 10 días.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿El resultado se ve inmediatamente?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cuánto dura el efecto?', 'La duración varía según la persona, la zona tratada, la dosis y otros factores. Generalmente el efecto dura varios meses (4-6 meses) y posteriormente la actividad muscular va recuperándose gradualmente.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cuánto dura el efecto?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿El tratamiento duele?', 'La aplicación se realiza mediante pequeñas inyecciones. Puede sentirse un pinchazo o molestia leve y momentánea.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿El tratamiento duele?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Me va a dejar la cara sin expresión?', 'No necesariamente. Un tratamiento correctamente indicado y aplicado busca disminuir las líneas de expresión manteniendo una apariencia natural. El resultado depende de la dosis, técnica y características de cada paciente.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Me va a dejar la cara sin expresión?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Me va a cambiar la forma de la cara?', 'Su objetivo no es cambiar los rasgos faciales, sino disminuir temporalmente la actividad de músculos específicos. Cualquier efecto sobre la apariencia depende de la zona tratada y de la técnica.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Me va a cambiar la forma de la cara?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Ayuda a prevenir las arrugas?', 'Al disminuir temporalmente la contracción repetitiva de ciertos músculos, puede ayudar a reducir la formación y profundización de algunas líneas de expresión.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Ayuda a prevenir las arrugas?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿El Botox elimina todas las arrugas?', 'No. Es especialmente efectivo para arrugas dinámicas. Las arrugas que están presentes incluso con el rostro en reposo pueden requerir otros tratamientos complementarios.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿El Botox elimina todas las arrugas?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Es lo mismo Botox que ácido hialurónico?', 'No. La toxina botulínica actúa principalmente sobre la actividad muscular, mientras que el ácido hialurónico puede utilizarse para hidratar, restaurar volumen o rellenar determinadas zonas, dependiendo de su formulación.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Es lo mismo Botox que ácido hialurónico?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo combinar Botox con otros tratamientos?', 'En algunos casos sí. La combinación debe planificarse de acuerdo con las necesidades del paciente y respetando los tiempos adecuados entre procedimientos.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo combinar Botox con otros tratamientos?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo maquillarme después?', 'Se deben seguir las indicaciones del profesional. Generalmente se recomienda evitar manipular o presionar intensamente las zonas tratadas inmediatamente después de la aplicación.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo maquillarme después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo hacer ejercicio después?', 'No en las primeras 24 horas, se recomienda seguir las indicaciones específicas del profesional respecto al ejercicio y otras actividades durante las horas posteriores al tratamiento.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo hacer ejercicio después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo tomar el sol después?', 'No durante las primeras 24 horas, es recomendable evitar la exposición solar intensa y seguir las medidas habituales de fotoprotección.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo tomar el sol después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Me quedan moretones?', 'Puede aparecer un pequeño hematoma, enrojecimiento o sensibilidad en los puntos de aplicación. Generalmente son temporales.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Me quedan moretones?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Tiene efectos secundarios?', 'Puede producir efectos temporales como dolor leve, inflamación, enrojecimiento o hematomas. Existen efectos adversos menos frecuentes, por lo que es importante realizar una valoración y explicar los riesgos antes del procedimiento.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Tiene efectos secundarios?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿El Botox es permanente?', 'No. Su efecto es temporal y la actividad muscular se recupera gradualmente con el tiempo.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿El Botox es permanente?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cada cuánto puedo aplicármelo?', 'El intervalo depende de la respuesta individual, las zonas tratadas y la valoración del profesional. No se recomienda repetirlo antes del tiempo indicado. Aproximadamente cada 4 a 6 meses.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cada cuánto puedo aplicármelo?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Desde qué edad puedo aplicarme Botox?', 'No existe una edad estética universal. La indicación debe basarse en las características de cada persona, sus objetivos y una valoración profesional.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Desde qué edad puedo aplicarme Botox?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Quiénes no son candidatos para Botox?', 'Existen diferentes contraindicaciones y precauciones. Deben valorarse antecedentes médicos, alergias, medicamentos, embarazo o lactancia, infecciones en la zona y otras condiciones antes de realizar el procedimiento.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Quiénes no son candidatos para Botox?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '-QUE CUIDADOS DEBO TENER AL APLICARME BOTOX?', 'Posterior a tu aplicación de toxina botulinica, es recomendable cuidar estos aspectos las siguientes 24 horas: No masajear la zona tratada No levantamiento de pesas o artículos pesados Evitar Saunas, baños de vapor o agua muy caliente. Evitar gorras, cascos, sombreros apretados Evitar consumo de alcohol No acostarse las siguientes 4 horas', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('-QUE CUIDADOS DEBO TENER AL APLICARME BOTOX?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo hacerme Botox si ya tengo arrugas marcadas?', 'Puede ayudar a suavizar las líneas dinámicas, pero el resultado dependerá de la profundidad de la arruga y de las características de la piel. En algunos casos puede ser necesario combinarlo con otros tratamientos.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo hacerme Botox si ya tengo arrugas marcadas?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿El Botox adelgaza la cara?', 'No es un tratamiento destinado a adelgazar el rostro. Sin embargo, cuando se utiliza en músculos específicos, como los maseteros, puede reducir temporalmente su volumen y modificar visualmente el contorno mandibular.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿El Botox adelgaza la cara?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué pasa cuando se acaba el efecto?', 'La actividad muscular comienza a recuperarse progresivamente y las líneas de expresión pueden volver a hacerse visibles. La piel no queda peor por suspender el tratamiento.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué pasa cuando se acaba el efecto?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿El resultado se ve natural?', 'El objetivo de un tratamiento bien planificado es conseguir una apariencia natural, suavizando las líneas sin perder la expresión facial.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿El resultado se ve natural?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Necesito una valoración antes del tratamiento?', 'Sí. La valoración permite analizar la anatomía facial, movimiento muscular, necesidades y objetivos para determinar si el tratamiento es adecuado.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Necesito una valoración antes del tratamiento?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Por qué debería realizarme Botox?', 'Porque puede ayudar a suavizar temporalmente las líneas de expresión y proporcionar una apariencia más descansada y armoniosa, siempre que exista una indicación adecuada y sea realizado por un profesional capacitado.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Por qué debería realizarme Botox?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, 'QUE MARCAS DE BOTOX MANEJAN?', 'DYSPORT XEOMEN BOTOX', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('QUE MARCAS DE BOTOX MANEJAN?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, 'QUE PRECIOS TIENE CADA UNA?', 'DYSPORT $5,500 XEOMEN $4,000 BOTOX $4,500', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('QUE PRECIOS TIENE CADA UNA?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, 'CUANTAS UNIDADES INCLUYE?', 'TERCIO SUPERIOR (FRENTE, ENTRECEJO, PATAS DE GALLO, BUNY LINES), APROX 50 UNIDADES', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('CUANTAS UNIDADES INCLUYE?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, 'EN CUANTO TIEMPO VEO RESULTADO?', 'LOS RESULTADOS EMPIEZAN A OBSERVARSE ENTRE EL DIA 3 AL 15 APROXIMADAMENTE.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('EN CUANTO TIEMPO VEO RESULTADO?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, 'EL COSTO INCLUYE RETOQUE?', 'SI, SI REQUIERES MAS UNIDADES YA ESTAN CUBIERTAS EN TU PAGO INICIAL.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('EL COSTO INCLUYE RETOQUE?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, 'QUE PASA SI YA NO ME VUELVO A APLICAR BOTOX DESPUES SE ESTA OCASIÓN?', 'EL MUSCULO VUELVE A SU NORMALIDAD EN MOVIMIENTO Y LAS ARRUGAS SE VUELVEN A FORMAR TAL CUAL ESTABAN EN UN PRINCIPIO SIN LA APLICACIÓN.', 5, true FROM beauty_services s WHERE s.slug = 'toxina-botulinica' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('QUE PASA SI YA NO ME VUELVO A APLICAR BOTOX DESPUES SE ESTA OCASIÓN?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué son los bioestimuladores?', 'Son tratamientos que buscan estimular los procesos naturales de la piel, principalmente la producción de colágeno y elastina, para mejorar progresivamente su firmeza y calidad.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué son los bioestimuladores?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Para qué sirven?', 'Ayudan a mejorar la firmeza, elasticidad, textura y apariencia general de la piel, contribuyendo a combatir los signos del envejecimiento.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Para qué sirven?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿De qué están hechos?', 'Existen diferentes tipos de bioestimuladores. Algunos contienen sustancias como ácido poli-Lláctico, hidroxiapatita de calcio o policaprolactona, dependiendo del producto utilizado.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿De qué están hechos?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Los bioestimuladores rellenan la cara?', 'Su objetivo principal no es rellenar ni aportar volumen inmediato, sino estimular la producción de colágeno. Sin embargo, algunos productos pueden generar cierto efecto de volumen dependiendo de su composición y técnica de aplicación.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Los bioestimuladores rellenan la cara?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿El resultado se ve inmediatamente?', 'Algunos productos pueden generar un cambio inicial por hidratación o inflamación, pero el efecto bioestimulador aparece de manera progresiva conforme el organismo produce nuevo colágeno.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿El resultado se ve inmediatamente?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cuándo voy a notar resultados?', 'Los resultados suelen desarrollarse gradualmente durante las semanas posteriores al tratamiento (45 a 90 días) y pueden continuar mejorando durante varios meses.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cuándo voy a notar resultados?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cuántas sesiones necesito?', 'Depende del producto, la edad, el estado de la piel y el objetivo del tratamiento. El protocolo debe personalizarse después de una valoración.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cuántas sesiones necesito?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿El tratamiento duele?', 'Puede producir cierta molestia durante la aplicación. Dependiendo del producto y la técnica, pueden utilizarse medidas para mejorar la comodidad del paciente.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿El tratamiento duele?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Me va a dejar la cara inflamada?', 'Puede presentarse inflamación, enrojecimiento, sensibilidad o pequeños hematomas después de la aplicación. La intensidad y duración dependen de la técnica y de cada persona.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Me va a dejar la cara inflamada?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cuánto dura el efecto?', 'La duración depende del bioestimulador utilizado, la zona tratada y las características individuales. Los resultados pueden mantenerse durante un periodo prolongado, de hasta 24 meses, pero no son permanentes.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cuánto dura el efecto?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Ayuda a producir colágeno?', 'Sí. Su principal finalidad es estimular los mecanismos naturales relacionados con la producción de colágeno, ayudando a mejorar progresivamente la estructura y firmeza de la piel.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Ayuda a producir colágeno?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Ayuda con la flacidez?', 'Sí, puede ser una alternativa para mejorar la apariencia de la flacidez leve a moderada, dependiendo de la causa y del grado de flacidez.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Ayuda con la flacidez?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Ayuda a mejorar las líneas de expresión?', 'Puede mejorar progresivamente la apariencia de líneas y arrugas al favorecer una piel más firme y con mejor calidad, aunque no elimina todas las arrugas.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Ayuda a mejorar las líneas de expresión?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Mejora la textura de la piel?', 'Sí. Al mejorar la calidad y estructura de la piel, puede contribuir a una textura más uniforme y firme.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Mejora la textura de la piel?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Se puede aplicar en cuello y escote?', 'Sí, Algunos bioestimuladores pueden utilizarse en estas zonas, siempre que el producto esté indicado para ellas y sea aplicado mediante la técnica correspondiente.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Se puede aplicar en cuello y escote?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo hacérmelo si soy joven?', 'La edad por sí sola no determina si una persona es candidata. Debe existir una necesidad estética real y realizarse una valoración profesional antes de indicar el tratamiento.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo hacérmelo si soy joven?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo combinar un bioestimulador con otros tratamientos?', 'En determinados casos sí, pero la combinación debe planificarse considerando el producto, las zonas tratadas, los tiempos entre procedimientos y las características de cada paciente.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo combinar un bioestimulador con otros tratamientos?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Es lo mismo que un Skinbooster?', 'No. El Skinbooster está principalmente enfocado en mejorar la hidratación y calidad superficial de la piel, mientras que los bioestimuladores buscan estimular procesos biológicos relacionados con la producción de colágeno.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Es lo mismo que un Skinbooster?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Es lo mismo que el PDRN de salmón?', 'No. Son activos diferentes y tienen mecanismos de acción distintos. El PDRN se utiliza principalmente por su enfoque regenerativo, mientras que los bioestimuladores están orientados principalmente a estimular la producción de', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Es lo mismo que el PDRN de salmón?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo maquillarme después?', 'Después de un tratamiento inyectable se recomienda seguir las indicaciones específicas del profesional y esperar el tiempo recomendado antes de aplicar maquillaje.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo maquillarme después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo tomar el sol después?', 'Se recomienda evitar la exposición solar intensa durante el periodo posterior al tratamiento y utilizar protector solar adecuadamente.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo tomar el sol después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué cuidados debo tener después?', 'Seguir las indicaciones específicas del producto y profesional, mantener una adecuada higiene de la zona, evitar manipularla innecesariamente y proteger la piel del sol.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué cuidados debo tener después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Tiene efectos secundarios?', 'Como cualquier procedimiento inyectable, pueden presentarse efectos temporales como inflamación, enrojecimiento, sensibilidad o hematomas. También existen riesgos menos frecuentes que deben explicarse durante el consentimiento informado.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Tiene efectos secundarios?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Quiénes no pueden realizarse este tratamiento?', 'La indicación depende del producto y de las condiciones de cada persona. Se deben valorar antecedentes, alergias, medicamentos, embarazo o lactancia, infecciones activas y otras posibles contraindicaciones antes de realizarlo.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Quiénes no pueden realizarse este tratamiento?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Los resultados se ven naturales?', 'Cuando está correctamente indicado y aplicado, el objetivo es conseguir una mejora progresiva y natural de la calidad y firmeza de la piel, sin modificar excesivamente los rasgos.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Los resultados se ven naturales?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿El resultado es permanente?', 'No. El envejecimiento continúa y el organismo sigue degradando el colágeno con el tiempo. Por ello pueden requerirse sesiones de mantenimiento.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿El resultado es permanente?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo hacerme un bioestimulador si tengo mucha flacidez?', 'Depende del grado y la causa de la flacidez. En casos avanzados, un bioestimulador puede no ser suficiente por sí solo y podría ser necesario valorar otras alternativas.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo hacerme un bioestimulador si tengo mucha flacidez?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué zonas se pueden tratar?', 'Dependiendo del producto, pueden tratarse zonas como rostro, cuello, escote, brazos u otras áreas con pérdida de firmeza. La indicación siempre debe corresponder al producto específico.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué zonas se pueden tratar?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cuál bioestimulador es mejor?', 'No existe uno que sea el mejor para todas las personas. La elección depende del estado de la piel, zona, objetivo, antecedentes y del producto disponible para el tratamiento.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cuál bioestimulador es mejor?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Por qué debería realizarme un bioestimulador?', 'Porque permite trabajar de manera progresiva sobre la calidad y firmeza de la piel, buscando estimular sus propios procesos de producción de colágeno y conseguir una apariencia más firme y rejuvenecida.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Por qué debería realizarme un bioestimulador?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, 'QUE MARCAS DE BIOESTIMULADORES MANEJAN?', 'SCULPTRA RADIESSE ULTRACOL', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('QUE MARCAS DE BIOESTIMULADORES MANEJAN?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, 'QUE PRECIOS TIENE CADA UNA?', 'SCULPTRA $12,000 RADIESSE $9,000 ULTRACOL $9,000', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('QUE PRECIOS TIENE CADA UNA?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, 'EN CUANTO TIEMPO VEO RESULTADO?', 'LOS RESULTADOS EMPIEZAN A OBSERVARSE ENTRE EL DIA 30 AL 90 APROXIMADAMENTE.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('EN CUANTO TIEMPO VEO RESULTADO?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, 'QUE CUIDADOS DEBO TENER AL APLICARME UN BIOESTIMULADOR?', 'Posterior a tu aplicación de bioestimulador, es recomendable cuidar estos aspectos: Dar masaje en rostro, o área tratada cada 5 horas, por 5 miutos por 5 días. Evitar Saunas, baños de vapor o agua muy caliente las primeras 24 horas post aplicación. Evitar consumo de alcohol las siguientes 24 horas', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('QUE CUIDADOS DEBO TENER AL APLICARME UN BIOESTIMULADOR?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, 'QUE PASA SI YA NO ME VUELVO A APLICAR BIOESTIMULADOR DESPUES SE ESTA OCASIÓN?', 'Para obtener mejores resultados hay que terminar las dosis indicadas por tu médico, si solo se aplica en esta ocasión y ya no continua su tratamiento, el efecto puede durar menos tiempo o ser menos notorio.', 5, true FROM beauty_services s WHERE s.slug = 'bioestimuladores' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('QUE PASA SI YA NO ME VUELVO A APLICAR BIOESTIMULADOR DESPUES SE ESTA OCASIÓN?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué es el PDRN de salmón?', 'Es un activo bioregenerador derivado de fragmentos de ADN purificado de salmón, utilizado para favorecer la regeneración y mejorar la calidad de la piel.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué es el PDRN de salmón?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Para qué sirve el PDRN salmon?', 'Ayuda a mejorar la hidratación, luminosidad, textura y apariencia general de la piel, además de favorecer los procesos naturales de reparación cutánea.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Para qué sirve el PDRN salmon?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿De qué está hecho el PDRN salmon?', 'El PDRN está compuesto por fragmentos de ADN purificado, generalmente obtenidos de especies de salmón.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿De qué está hecho el PDRN salmon?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Es realmente de salmón?', 'Sí. El PDRN tradicionalmente utilizado en estética se obtiene a partir de ADN purificado proveniente de salmón o especies relacionadas.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Es realmente de salmón?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿El tratamiento duele?', 'La molestia depende de la técnica utilizada. Cuando se aplica mediante microinyecciones puede sentirse un pequeño pinchazo; con técnicas no invasivas, la sensación suele ser mucho menor.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿El tratamiento duele?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Se aplica con inyecciones?', 'Depende del protocolo y del producto. Algunos tratamientos con PDRN son inyectables, mientras que otros están formulados para aplicaciones tópicas o mediante determinados equipos.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Se aplica con inyecciones?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cuánto dura el procedimiento?', 'Generalmente es un procedimiento relativamente rápido, aunque el tiempo depende de la técnica, la zona y el protocolo utilizado.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cuánto dura el procedimiento?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cuántas sesiones necesito?', 'El número de sesiones depende del estado de la piel y del objetivo del tratamiento. Lo ideal es establecer un protocolo personalizado después de valorar la piel.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cuántas sesiones necesito?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cuándo voy a ver resultados?', 'Algunos cambios, como mayor luminosidad e hidratación, pueden apreciarse después de las primeras sesiones. Los resultados relacionados con la calidad y regeneración de la piel requieren mayor tiempo y constancia.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cuándo voy a ver resultados?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué resultados puedo esperar?', 'Una piel con apariencia más hidratada, luminosa, uniforme y con mejor textura. Los resultados pueden variar según cada persona.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué resultados puedo esperar?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Ayuda a producir colágeno?', 'Puede favorecer procesos relacionados con la reparación y actividad de las células de la piel, contribuyendo indirectamente a una mejor calidad cutánea.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Ayuda a producir colágeno?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Sirve para manchas o marcas de acné?', 'Puede ayudar a mejorar la apariencia y calidad de la piel, pero no debe considerarse un tratamiento único para todas las manchas o cicatrices. Es importante valorar primero el tipo de alteración.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Sirve para manchas o marcas de acné?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Ayuda con las líneas de expresión?', 'Puede mejorar la apariencia de líneas finas al favorecer una piel más hidratada y de mejor calidad, aunque no sustituye tratamientos específicos para arrugas profundas.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Ayuda con las líneas de expresión?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Mejora la textura y luminosidad?', 'Sí. Es uno de los objetivos más buscados del tratamiento, ya que puede ayudar a conseguir una piel de apariencia más uniforme, hidratada y luminosa.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Mejora la textura y luminosidad?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Es bueno para piel seca o deshidratada?', 'Puede ser una buena opción para mejorar la apariencia de la piel deshidratada, siempre realizando previamente una valoración adecuada.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Es bueno para piel seca o deshidratada?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Se puede aplicar alrededor de los ojos?', 'Depende del producto, su autorización de uso y la técnica. La zona periocular requiere especial cuidado y debe tratarse únicamente cuando el producto y el profesional estén indicados para esa zona.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Se puede aplicar alrededor de los ojos?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Se puede combinar con otros tratamientos?', 'En algunos protocolos sí puede combinarse con otros tratamientos, pero debe determinarse según el producto utilizado, la técnica y las condiciones de la piel.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Se puede combinar con otros tratamientos?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué cuidados debo tener después?', 'Se recomienda mantener la piel limpia e hidratada, utilizar protector solar y evitar productos irritantes o procedimientos agresivos durante el periodo indicado por el profesional.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué cuidados debo tener después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo maquillarme después?', 'Depende de la técnica utilizada. Si se realizaron microinyecciones, normalmente se recomienda esperar el tiempo indicado por el profesional antes de aplicar maquillaje.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo maquillarme después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo tomar el sol después?', 'Es recomendable evitar la exposición solar directa y utilizar protector solar de amplio espectro para proteger la piel durante la recuperación.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo tomar el sol después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Tiene efectos secundarios?', 'Dependiendo de la técnica, pueden presentarse temporalmente enrojecimiento, sensibilidad, inflamación leve o pequeños puntos en la zona tratada.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Tiene efectos secundarios?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puede causar alergia?', 'Como cualquier producto, existe posibilidad de reacción. Es importante revisar antecedentes, ingredientes y contraindicaciones antes de realizar el procedimiento.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puede causar alergia?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Deja inflamación o pequeños puntos?', 'Si se utiliza una técnica con microinyecciones, puede presentarse inflamación leve, enrojecimiento o pequeños puntos que generalmente son temporales.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Deja inflamación o pequeños puntos?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Quiénes no pueden realizarse este tratamiento?', 'No todas las personas son candidatas. Se debe realizar una valoración previa y considerar embarazo, lactancia, alergias, infecciones activas, alteraciones de la piel y otras condiciones que puedan contraindicar el procedimiento.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Quiénes no pueden realizarse este tratamiento?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Es lo mismo que un skinbooster?', 'No necesariamente. El PDRN y los skinboosters son tratamientos diferentes, aunque ambos pueden buscar mejorar la hidratación y calidad de la piel.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Es lo mismo que un skinbooster?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cuál es la diferencia entre PDRN, ácido hialurónico y bioestimuladores?', 'Son activos y tratamientos diferentes. El ácido hialurónico se utiliza principalmente para hidratación y, dependiendo de su formulación, para aportar volumen; los bioestimuladores buscan estimular procesos relacionados con la producción de colágeno; y el PDRN se enfoca principalmente en la regeneración y calidad de la piel.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cuál es la diferencia entre PDRN, ácido hialurónico y bioestimuladores?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Los resultados son permanentes?', 'No. La piel continúa envejeciendo y los resultados pueden disminuir con el tiempo. Por eso suelen recomendarse sesiones de mantenimiento y una buena rutina de cuidado en casa.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Los resultados son permanentes?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cada cuánto tiempo puedo realizarlo?', 'La frecuencia depende del producto, la técnica y el protocolo utilizado. Se debe respetar el intervalo recomendado por el fabricante y el profesional.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cada cuánto tiempo puedo realizarlo?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Desde qué edad se recomienda?', 'No existe una edad universal para todas las personas. La indicación debe basarse en las necesidades de la piel y en una valoración profesional.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Desde qué edad se recomienda?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué diferencia hay entre PDRN de salmón y otros bioestimuladores?', 'Su mecanismo y composición son diferentes. El PDRN se utiliza principalmente para favorecer la regeneración y mejorar la calidad de la piel, mientras que otros bioestimuladores tienen como objetivo principal estimular la producción de colágeno mediante mecanismos distintos.', 5, true FROM beauty_services s WHERE s.slug = 'pdrn-salmon' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué diferencia hay entre PDRN de salmón y otros bioestimuladores?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué es un Skinbooster?', 'Es un tratamiento diseñado para mejorar la calidad de la piel desde el interior, aportando principalmente hidratación, luminosidad y una apariencia más uniforme.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué es un Skinbooster?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿De qué está hecho un Skinbooster?', 'Los Skinboosters pueden contener diferentes activos dependiendo del producto. Uno de los más utilizados es el ácido hialurónico no reticulado, además de vitaminas, aminoácidos, antioxidantes u otros componentes destinados a mejorar la calidad de la piel.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿De qué está hecho un Skinbooster?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Para qué sirve?', 'Ayuda a mejorar la hidratación, elasticidad, luminosidad y textura de la piel, proporcionando un aspecto más fresco y saludable.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Para qué sirve?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Es lo mismo que un relleno de ácido hialurónico?', 'No. Aunque algunos Skinboosters contienen ácido hialurónico, su objetivo principal es mejorar la calidad e hidratación de la piel, no aportar volumen o modificar los rasgos faciales como ocurre con un relleno.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Es lo mismo que un relleno de ácido hialurónico?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿El Skinbooster da volumen?', 'Su finalidad no es aumentar significativamente el volumen. Está enfocado principalmente en hidratar y mejorar la calidad de la piel.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿El Skinbooster da volumen?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿El tratamiento duele?', 'La sensación depende de la técnica utilizada y de la sensibilidad de cada persona. Si se realiza mediante microinyecciones, pueden sentirse pequeños pinchazos y cierta sensibilidad temporal.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿El tratamiento duele?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cómo se aplica?', 'Depende del producto y del protocolo. Los Skinboosters inyectables se aplican mediante pequeñas inyecciones superficiales o en puntos específicos de la piel.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cómo se aplica?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cuánto dura el procedimiento?', 'Generalmente es un tratamiento de corta duración, aunque el tiempo puede variar dependiendo de la zona y la técnica utilizada.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cuánto dura el procedimiento?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cuántas sesiones necesito?', 'Depende de las necesidades de cada piel y del producto utilizado. Habitualmente se recomienda un protocolo de varias sesiones para obtener resultados progresivos.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cuántas sesiones necesito?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cuándo comenzaré a notar resultados?', 'La hidratación y luminosidad pueden comenzar a apreciarse después del tratamiento, mientras que la mejora general de la calidad de la piel puede ser progresiva.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cuándo comenzaré a notar resultados?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué resultados puedo esperar?', 'Una piel con mayor hidratación, luminosidad y suavidad, además de una apariencia más uniforme y saludable.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué resultados puedo esperar?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Ayuda con las líneas de expresión?', 'Puede mejorar la apariencia de líneas finas relacionadas con deshidratación y pérdida de calidad cutánea, aunque no sustituye tratamientos específicos para arrugas profundas.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Ayuda con las líneas de expresión?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Ayuda a mejorar la piel seca o deshidratada?', 'Sí. Es uno de los tratamientos más utilizados para mejorar la hidratación y apariencia de una piel deshidratada.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Ayuda a mejorar la piel seca o deshidratada?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Mejora la textura de la piel?', 'Sí, puede contribuir a que la piel se vea más suave, uniforme y con una textura de mejor calidad.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Mejora la textura de la piel?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Se puede aplicar en el contorno de ojos?', 'Algunos productos están específicamente formulados para utilizarse en esta zona. Siempre debe verificarse que el producto esté indicado para el área periocular y realizarse con una técnica adecuada.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Se puede aplicar en el contorno de ojos?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo hacérmelo si tengo piel sensible?', 'Puede ser posible, pero primero debe realizarse una valoración para determinar si la piel se encuentra en condiciones adecuadas para el tratamiento.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo hacérmelo si tengo piel sensible?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo combinarlo con otros tratamientos?', 'En algunos casos sí. La combinación depende del producto, la técnica y las características de la piel, por lo que debe establecerse un protocolo personalizado.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo combinarlo con otros tratamientos?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Me va a dejar la cara inflamada?', 'Puede presentarse inflamación leve, enrojecimiento o sensibilidad, especialmente cuando se realiza mediante microinyecciones. Estos efectos suelen ser temporales.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Me va a dejar la cara inflamada?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cuánto tiempo tarda en recuperarse la piel?', 'El tiempo de recuperación depende de la técnica y de cada persona. Generalmente las molestias y el enrojecimiento disminuyen progresivamente.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cuánto tiempo tarda en recuperarse la piel?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo maquillarme después?', 'Después de un Skinbooster inyectable se suele recomendar esperar el tiempo indicado por el profesional antes de aplicar maquillaje, para evitar irritación y reducir riesgos.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo maquillarme después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo tomar el sol después?', 'Se recomienda evitar la exposición solar directa y utilizar protector solar de amplio espectro durante el periodo posterior al tratamiento.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo tomar el sol después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué cuidados debo tener después?', 'Mantener la piel limpia e hidratada, utilizar protector solar y evitar temporalmente productos o procedimientos que puedan irritar la piel.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué cuidados debo tener después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Los resultados son permanentes?', 'No. Los resultados disminuyen progresivamente, por lo que pueden realizarse sesiones de mantenimiento según las necesidades de cada piel y las indicaciones del producto.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Los resultados son permanentes?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cada cuánto puedo realizarme un Skinbooster?', 'La frecuencia depende del producto y del protocolo utilizado. Se debe respetar el intervalo recomendado por el fabricante y el profesional.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cada cuánto puedo realizarme un Skinbooster?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Quiénes no son candidatos para este tratamiento?', 'La candidatura depende del estado de salud, la piel y el producto utilizado. Se deben considerar posibles contraindicaciones como infecciones activas en la zona, alergias a componentes y determinadas condiciones médicas.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Quiénes no son candidatos para este tratamiento?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cuál es la diferencia entre Skinbooster y PDRN de salmón?', 'Son tratamientos diferentes. El Skinbooster está principalmente orientado a mejorar la hidratación y calidad de la piel, mientras que el PDRN se utiliza principalmente por su enfoque regenerativo y de reparación cutánea.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cuál es la diferencia entre Skinbooster y PDRN de salmón?'));
