INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Desde qué edad puedo realizarme un Skinbooster?', 'No existe una edad única para todos los casos. La indicación debe basarse en las necesidades de la piel y en una valoración profesional.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Desde qué edad puedo realizarme un Skinbooster?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Se puede utilizar en rostro, cuello y escote?', 'Dependiendo del producto, sí. Algunos Skinboosters están indicados para diferentes zonas, pero siempre debe verificarse la autorización y recomendación específica del producto.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Se puede utilizar en rostro, cuello y escote?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Por qué debería hacerme un Skinbooster?', 'Porque es una opción enfocada en mejorar la calidad de la piel, especialmente cuando buscamos mayor hidratación, luminosidad, suavidad y una apariencia más saludable sin buscar cambios drásticos en los rasgos faciales.', 5, true FROM beauty_services s WHERE s.slug = 'skinbooster' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Por qué debería hacerme un Skinbooster?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué es NCTF?', 'Es un tratamiento de revitalización cutánea que utiliza una fórmula con múltiples activos para mejorar la calidad, hidratación y luminosidad de la piel.', 5, true FROM beauty_services s WHERE s.slug = 'nctf-revitalizante' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué es NCTF?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿De qué está compuesto?', 'Su fórmula contiene ácido hialurónico no reticulado y una combinación de vitaminas, aminoácidos, minerales, coenzimas y otros componentes destinados a favorecer la revitalización de la piel.', 5, true FROM beauty_services s WHERE s.slug = 'nctf-revitalizante' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿De qué está compuesto?'));
