INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿El NCTF estimula el colágeno?', 'Puede favorecer procesos relacionados con la actividad celular y la síntesis de componentes de la matriz extracelular, contribuyendo a mejorar progresivamente la calidad de la piel.', 5, true FROM beauty_services s WHERE s.slug = 'nctf-revitalizante' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿El NCTF estimula el colágeno?'));
