INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Es lo mismo que el PDRN de salmón?', 'No. Son fórmulas diferentes. El NCTF combina múltiples activos para revitalizar la piel, mientras que el PDRN se basa principalmente en polinucleótidos derivados de ADN purificado.', 5, true FROM beauty_services s WHERE s.slug = 'nctf-revitalizante' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Es lo mismo que el PDRN de salmón?'));
