INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Ayuda con manchas?', 'NCTF no debe considerarse un tratamiento específico para eliminar manchas. Puede mejorar la calidad general de la piel, pero las alteraciones de pigmentación requieren una valoración y tratamiento específico.', 5, true FROM beauty_services s WHERE s.slug = 'nctf-revitalizante' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Ayuda con manchas?'));
