INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo aplicarlo alrededor de los ojos?', 'Algunas formulaciones y protocolos pueden estar indicados para determinadas zonas perioculares. Siempre debe verificarse la indicación específica del producto y utilizar una técnica adecuada.', 5, true FROM beauty_services s WHERE s.slug = 'nctf-revitalizante' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo aplicarlo alrededor de los ojos?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo combinarlo con otros tratamientos?', 'En algunos casos sí. La combinación debe establecerse de manera personalizada, considerando el tipo de piel, producto utilizado y tiempos adecuados entre procedimientos.', 5, true FROM beauty_services s WHERE s.slug = 'nctf-revitalizante' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo combinarlo con otros tratamientos?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo maquillarme después?', 'Después de una aplicación mediante microinyecciones se recomienda seguir las indicaciones del profesional y respetar el tiempo establecido antes de aplicar maquillaje.', 5, true FROM beauty_services s WHERE s.slug = 'nctf-revitalizante' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo maquillarme después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo tomar el sol después?', 'Se recomienda evitar la exposición solar intensa y utilizar protector solar de amplio espectro para proteger la piel después del tratamiento.', 5, true FROM beauty_services s WHERE s.slug = 'nctf-revitalizante' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo tomar el sol después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué cuidados debo tener después?', 'Mantener la piel limpia e hidratada, utilizar protector solar y evitar temporalmente productos o procedimientos que puedan irritar la zona tratada.', 5, true FROM beauty_services s WHERE s.slug = 'nctf-revitalizante' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué cuidados debo tener después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Tiene efectos secundarios?', 'Puede presentarse enrojecimiento, sensibilidad, inflamación leve o pequeños hematomas. Como cualquier procedimiento inyectable, también existen riesgos menos frecuentes que deben explicarse previamente.', 5, true FROM beauty_services s WHERE s.slug = 'nctf-revitalizante' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Tiene efectos secundarios?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Quiénes no pueden realizarse NCTF?', 'La indicación depende del producto y de cada paciente. Deben valorarse antecedentes, alergias, embarazo o lactancia, infecciones activas, alteraciones cutáneas y otras posibles contraindicaciones.', 5, true FROM beauty_services s WHERE s.slug = 'nctf-revitalizante' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Quiénes no pueden realizarse NCTF?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Desde qué edad se recomienda?', 'No existe una edad universal. Su indicación debe basarse en las necesidades de la piel y en una valoración profesional.', 5, true FROM beauty_services s WHERE s.slug = 'nctf-revitalizante' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Desde qué edad se recomienda?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Es un tratamiento preventivo o correctivo?', 'Puede utilizarse con un enfoque preventivo para mantener la calidad de la piel o como parte de un protocolo para mejorar signos como deshidratación, pérdida de luminosidad y cambios en la textura.', 5, true FROM beauty_services s WHERE s.slug = 'nctf-revitalizante' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Es un tratamiento preventivo o correctivo?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿El resultado se ve natural?', 'Sí. Su objetivo es mejorar progresivamente la calidad de la piel sin modificar los rasgos faciales ni aportar un volumen significativo.', 5, true FROM beauty_services s WHERE s.slug = 'nctf-revitalizante' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿El resultado se ve natural?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Por qué debería realizarme NCTF Revitalizante?', 'Porque es un tratamiento integral de revitalización que combina diferentes activos para mejorar hidratación, luminosidad, textura y calidad general de la piel, buscando una apariencia más fresca y saludable.', 5, true FROM beauty_services s WHERE s.slug = 'nctf-revitalizante' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Por qué debería realizarme NCTF Revitalizante?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué es la mesoterapia capilar?', 'Es un tratamiento que consiste en aplicar pequeñas cantidades de activos directamente en el cuero cabelludo, con el objetivo de mejorar las condiciones del folículo y favorecer la calidad y crecimiento del cabello.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué es la mesoterapia capilar?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Para qué sirve?', 'Puede ayudar a mejorar la nutrición del cuero cabelludo, fortalecer el cabello y favorecer un entorno adecuado para el crecimiento capilar.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Para qué sirve?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué se aplica durante el tratamiento?', 'Depende del protocolo y producto utilizado. Puede incluir diferentes activos, como vitaminas, aminoácidos, minerales, ácido hialurónico u otros componentes destinados al cuidado capilar.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué se aplica durante el tratamiento?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Ayuda contra la caída del cabello?', 'Puede contribuir a disminuir determinados tipos de caída y mejorar la calidad del cabello, pero primero es importante identificar la causa de la caída para determinar si la mesoterapia es adecuada.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Ayuda contra la caída del cabello?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Hace que crezca cabello nuevo?', 'Puede favorecer la actividad de los folículos que aún son funcionales, ayudando a mejorar el crecimiento en determinadas condiciones. No puede hacer crecer cabello en un folículo que ya no es viable.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Hace que crezca cabello nuevo?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Fortalece el cabello?', 'Sí. Al mejorar las condiciones del cuero cabelludo y aportar determinados activos, puede contribuir a que el cabello tenga una apariencia más fuerte y saludable.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Fortalece el cabello?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cuántas sesiones necesito?', 'Depende del estado del cuero cabelludo, el tipo de caída y el protocolo utilizado. Generalmente se recomienda un esquema de varias sesiones para obtener resultados progresivos.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cuántas sesiones necesito?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cuándo comenzaré a notar resultados?', 'Los resultados no son inmediatos. La disminución de la caída y las mejoras en la calidad o crecimiento del cabello requieren constancia y tiempo.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cuándo comenzaré a notar resultados?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿El tratamiento duele?', 'Puede sentirse una molestia leve debido a las pequeñas aplicaciones en el cuero cabelludo. La sensibilidad varía de una persona a otra.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿El tratamiento duele?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Me queda inflamado el cuero cabelludo?', 'Puede presentarse enrojecimiento, sensibilidad o pequeñas elevaciones en los puntos de aplicación, que generalmente son temporales.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Me queda inflamado el cuero cabelludo?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Cuánto dura una sesión?', 'El tiempo depende del protocolo, la cantidad de producto y la zona a tratar, pero generalmente es un procedimiento relativamente rápido.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Cuánto dura una sesión?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo lavarme el cabello después?', 'Depende del producto y protocolo utilizado. Se recomienda seguir las indicaciones específicas proporcionadas después de la sesión.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo lavarme el cabello después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo hacer ejercicio después?', 'Es recomendable seguir las indicaciones posteriores del profesional, ya que algunas actividades pueden aumentar temporalmente la sudoración o irritación del cuero cabelludo.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo hacer ejercicio después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo teñirme el cabello después?', 'Es preferible dejar pasar un periodo adecuado antes de realizar procedimientos químicos que puedan irritar el cuero cabelludo.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo teñirme el cabello después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo usar productos para el cabello después?', 'Se recomienda evitar temporalmente productos potencialmente irritantes y utilizar únicamente los productos indicados por el profesional.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo usar productos para el cabello después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿La mesoterapia capilar sirve para hombres y mujeres?', 'Sí. Puede utilizarse tanto en hombres como en mujeres, siempre que exista una indicación adecuada y el protocolo sea personalizado.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿La mesoterapia capilar sirve para hombres y mujeres?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Sirve para entradas o zonas con poca densidad?', 'Puede ayudar cuando existen folículos funcionales en la zona. Si el folículo ya no es viable, la mesoterapia no puede regenerarlo.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Sirve para entradas o zonas con poca densidad?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Sirve para la alopecia?', 'Depende del tipo de alopecia. Algunas condiciones pueden beneficiarse de tratamientos complementarios, mientras que otras requieren valoración y manejo médico especializado.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Sirve para la alopecia?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿La mesoterapia detiene completamente la caída?', 'No necesariamente. La caída del cabello puede tener múltiples causas, por lo que el tratamiento debe dirigirse al origen del problema cuando sea posible.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿La mesoterapia detiene completamente la caída?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Es lo mismo que un tratamiento capilar tópico?', 'No. Los productos tópicos se aplican sobre la superficie del cuero cabelludo, mientras que la mesoterapia utiliza microinyecciones para introducir los activos en capas superficiales de la piel.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Es lo mismo que un tratamiento capilar tópico?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Es lo mismo que PRP?', 'No. El PRP utiliza plasma obtenido de la propia sangre del paciente, mientras que la mesoterapia utiliza una fórmula de activos determinada por el producto y protocolo empleado.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Es lo mismo que PRP?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Se puede combinar con otros tratamientos capilares?', 'En determinados casos sí. La combinación debe establecerse según la causa de la caída, el estado del cuero cabelludo y los tratamientos utilizados.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Se puede combinar con otros tratamientos capilares?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Tiene efectos secundarios?', 'Puede producir molestias, enrojecimiento, sensibilidad, inflamación leve o pequeños hematomas. Los riesgos dependen de los activos y de la técnica utilizada.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Tiene efectos secundarios?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Quiénes no pueden realizarse mesoterapia capilar?', 'La candidatura depende del estado de salud y del producto utilizado. Deben valorarse alergias, infecciones o lesiones en el cuero cabelludo, embarazo o lactancia, medicamentos y otras posibles contraindicaciones.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Quiénes no pueden realizarse mesoterapia capilar?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Necesito una valoración antes de comenzar?', 'Sí. La valoración permite observar el cuero cabelludo, conocer el tipo de caída y determinar si el tratamiento es adecuado o si es necesario acudir con un dermatólogo o especialista.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Necesito una valoración antes de comenzar?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Los resultados son permanentes?', 'No necesariamente. El cabello continúa estando influenciado por factores hormonales, genéticos, nutricionales y ambientales, por lo que pueden ser necesarias sesiones de mantenimiento.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Los resultados son permanentes?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Desde qué edad se puede realizar?', 'La edad no es el único factor. Debe determinarse la causa de la caída y valorar si el tratamiento es apropiado para la persona.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Desde qué edad se puede realizar?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Puedo realizarme el tratamiento si tengo caspa o irritación?', 'Primero debe valorarse y controlar la condición del cuero cabelludo. No es recomendable realizar microinyecciones sobre una zona con infección o inflamación activa.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Puedo realizarme el tratamiento si tengo caspa o irritación?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Qué cuidados debo tener después?', 'Mantener el cuero cabelludo limpio según las indicaciones, evitar manipular excesivamente la zona y respetar las recomendaciones sobre lavado, ejercicio, productos capilares y exposición solar.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Qué cuidados debo tener después?'));
INSERT INTO beauty_faqs (service_id, question, answer, priority, active) SELECT s.id, '¿Por qué debería realizarme una mesoterapia capilar?', 'Porque puede ser una herramienta complementaria para mejorar las condiciones del cuero cabelludo y fortalecer el cabello, siempre que exista una indicación adecuada y se utilice un protocolo personalizado.', 5, true FROM beauty_services s WHERE s.slug = 'mesoterapia-capilar' AND NOT EXISTS (SELECT 1 FROM beauty_faqs f WHERE f.service_id = s.id AND lower(f.question) = lower('¿Por qué debería realizarme una mesoterapia capilar?'));
